import {renderLessonTree} from './lesson-one-view.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===Infinity?'∞':v===-Infinity?'−∞':v===null?'—':v;
function svg(content,w=650,h=330,label='算法状态图'){return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}">${content}</svg>`}
function trees(roots,hot=[]){if(!roots.length)return '<div class="empty-state">∅<span>当前结构为空</span></div>';let all=[],edges=[],cursor=0,maxDepth=0;function visit(n,depth){const children=n.children||[n.left,n.right].filter(Boolean);let locations=[],x;if(n.children){for(const ch of children)locations.push(visit(ch,depth+1));x=children.length?locations.reduce((a,b)=>a+b,0)/locations.length:(++cursor)*90}else{if(n.left)locations.push(visit(n.left,depth+1));x=(++cursor)*90;if(n.right)locations.push(visit(n.right,depth+1))}maxDepth=Math.max(maxDepth,depth);all.push({n,x,y:40+depth*92});children.forEach((ch,j)=>edges.push([x,40+depth*92,locations[j],40+(depth+1)*92]));return x}roots.forEach(r=>{visit(r,0);cursor+=.5});const w=Math.max(400,(cursor+.8)*90),h=Math.max(275,100+maxDepth*92);return `<div class="tree-canvas" style="min-width:${Math.min(1100,Math.max(300,w*.9))}px">`+svg(`${edges.map(([x,y,a,b])=>`<path class="edge" d="M${x} ${y+21}L${a} ${b-21}"/>`).join('')}${all.map(({n,x,y})=>`<g opacity="${n.meta==='pruned'?.3:1}"><circle class="node ${n.color||''} ${hot.includes(n.v)?'hot':''}" cx="${x}" cy="${y}" r="23"/><text class="${n.color==='black'&&!hot.includes(n.v)?'white-text':''}" x="${x}" y="${y+5}" text-anchor="middle" font-size="${String(n.label??n.v).length>3?12:15}">${esc(n.label??n.v)}</text>${n.meta!==undefined?`<text x="${x}" y="${y+42}" text-anchor="middle" font-size="13">${esc(n.meta)}</text>`:''}</g>`).join('')}`,w,h,'树结构：节点颜色和注记表示当前算法状态')+'</div>'}
const row=r=>`<div class="row-label">${esc(r.label||'')}</div><div class="array-row">${r.values?.length?r.values.map((x,i)=>`<span class="cell ${(r.hot||[]).includes(i)?'hot':''}">${esc(fmt(x))}</span>`).join(''):'<span class="empty-row">∅</span>'}</div>`;
function bplus(f){const levels=f.levels,loc=new Map(),w=Math.max(500,Math.max(...levels.map(l=>l.length))*165),h=Math.max(290,levels.length*105+50);levels.forEach((l,d)=>l.forEach((n,i)=>loc.set(n.id,{x:(i+.5)*w/l.length,y:40+d*105})));let out='';levels.forEach(l=>l.forEach(n=>{const{x,y}=loc.get(n.id);n.children.forEach(id=>{const p=loc.get(id);out+=`<path class="edge" d="M${x} ${y+18}L${p.x} ${p.y-18}"/>`})}));const leaves=levels.at(-1);for(let i=0;i<leaves.length-1;i++){const a=loc.get(leaves[i].id),b=loc.get(leaves[i+1].id);out+=`<path d="M${a.x+55} ${a.y+27}H${b.x-55}" fill="none" stroke="#73974e" stroke-dasharray="4 4"/><text x="${b.x-61}" y="${b.y+32}" font-size="16">›</text>`}levels.forEach(l=>l.forEach(n=>{const{x,y}=loc.get(n.id),width=Math.max(70,n.keys.length*30+15);out+=`<rect x="${x-width/2}" y="${y-19}" width="${width}" height="38" rx="4" fill="${f.hot.includes(n.id)?'#c1e784':n.leaf?'#e9f0e1':'#fff'}" stroke="#64886c"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="13">${n.keys.length?esc(n.keys.join(' · ')):'∅'}</text><text x="${x}" y="${y+47}" text-anchor="middle" font-size="11">${n.leaf?'数据叶页':'分隔键'}</text>`}));return `<div style="min-width:${Math.max(300,w*.7)}px">${svg(out,w,h,'B+ 树内部键、叶页与叶链')}</div>`}
function plot(f){const pts=f.points,minX=Math.min(...pts.map(p=>p.x)),maxX=Math.max(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y)),scale=Math.min(540/Math.max(1,maxX-minX),235/Math.max(1,maxY-minY)),X=x=>55+(x-minX)*scale,Y=y=>285-(y-minY)*scale;let out=`<path d="M45 20V295H620" fill="none" stroke="#bbc8b7"/><text x="615" y="315" font-size="12">x</text><text x="25" y="25" font-size="12">y</text>`;if(f.line!==undefined)out+=`<path d="M${X(f.line)} 25V290" stroke="#b87a41" stroke-dasharray="5 5"/>`;if(f.assignments)pts.forEach((p,i)=>{const c=pts[f.assignments[i]];if(c)out+=`<path d="M${X(p.x)} ${Y(p.y)}L${X(c.x)} ${Y(c.y)}" class="edge" stroke-dasharray="4 4"/>`});if(f.pair?.length===2){const[a,b]=f.pair.map(i=>pts[i]);out+=`<path d="M${X(a.x)} ${Y(a.y)}L${X(b.x)} ${Y(b.y)}" stroke="#bc5a32" stroke-width="3"/>`}pts.forEach(p=>{const center=f.centers?.includes(p.id),hot=f.hot?.includes(p.id);out+=`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="${center?13:7}" fill="${center?'#235e4b':hot?'#c1e784':'white'}" stroke="#55784b" stroke-width="2"/><text x="${X(p.x)+11}" y="${Y(p.y)-12}" font-size="12">${p.id+1} (${p.x},${p.y})</text>`});return svg(out,650,330,'输入点、当前候选点对或已选择中心')}
function graph(f){const{n,edges}=f,p=Array.from({length:n},(_,i)=>({x:320+130*Math.cos(-Math.PI/2+i*2*Math.PI/n),y:165+125*Math.sin(-Math.PI/2+i*2*Math.PI/n)})),tour=new Set();if(f.tour)for(let i=0;i<f.tour.length-1;i++)tour.add([f.tour[i],f.tour[i+1]].sort((a,b)=>a-b).join(','));let out='';edges.forEach(([a,b,w])=>{const u=p[a],v=p[b],selected=f.side?f.side[a]!==f.side[b]:tour.has([a,b].sort((a,b)=>a-b).join(',')),x=(u.x+v.x)/2,y=(u.y+v.y)/2;out+=`<path d="M${u.x} ${u.y}L${v.x} ${v.y}" stroke="${selected?'#51813d':'#c1cabf'}" stroke-width="${selected?3:1.5}" ${!f.side&&w===2?'stroke-dasharray="5 5"':''}/><rect x="${x-10}" y="${y-10}" width="20" height="20" rx="7" fill="#fbfcf9"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12">${w}</text>`});p.forEach((pt,i)=>{out+=`<circle cx="${pt.x}" cy="${pt.y}" r="21" fill="${f.hot?.includes(i)?'#c1e784':f.side?.[i]?'#235e4b':'white'}" stroke="#55774a" stroke-width="2"/><text x="${pt.x}" y="${pt.y+5}" class="${f.side?.[i]&&!f.hot?.includes(i)?'white-text':''}" text-anchor="middle" font-size="15">${i}</text>`});return svg(out,640,335,'无向带权图，突出当前割边或巡回')}
function intervals(f){const min=Math.min(0,...f.items.map(x=>x.s)),max=Math.max(...f.items.map(x=>x.e)),X=x=>65+(x-min)/(max-min)*530,h=f.items.length*29+40;let out='';f.items.forEach((a,i)=>{const y=i*29+12,chosen=f.chosen.includes(a.id),no=f.rejected.includes(a.id);out+=`<text x="10" y="${y+15}" font-size="12">a${a.id+1}</text><rect x="${X(a.s)}" y="${y}" width="${Math.max(2,X(a.e)-X(a.s))}" height="21" rx="3" fill="${chosen?'#bce18a':no?'#e2e5df':'#cddcc3'}" stroke="${f.active===a.id?'#245c44':'none'}"/><text x="${X(a.s)+5}" y="${y+15}" font-size="11">[${a.s},${a.e}) ${chosen?'✓':no?'×':''}</text>`});return svg(out,630,h,'活动时间区间与贪心选择结果')}
export function renderFrame(f){switch(f.kind){case'lesson-tree':return renderLessonTree(f);case'tree':return trees(f.roots,f.hot);case'bplus':return bplus(f);case'array':return row({values:f.array,hot:f.hot});case'rows':return f.rows.map(row).join('');case'matrix':return `<div class="table-wrap"><table aria-label="动态规划状态表"><thead><tr><th>i / j</th>${f.matrix[0].map((_,i)=>`<th>${esc(f.labels?.[i]??i)}</th>`).join('')}</tr></thead><tbody>${f.matrix.map((r,i)=>`<tr><th>${esc(f.labels?.[i]??i)}</th>${r.map((v,j)=>`<td class="${f.hot?.some(([a,b])=>a===i&&b===j)?'selected':''}">${esc(fmt(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;case'board':return `<div class="board" style="grid-template-columns:repeat(${f.n},1fr)" role="img" aria-label="${f.n} 皇后棋盘，已放 ${f.queens.length} 个皇后">${Array.from({length:f.n*f.n},(_,i)=>{const r=Math.floor(i/f.n),c=i%f.n,attempt=f.attempt?.[0]===r&&f.attempt?.[1]===c;return `<span class="square ${(r+c)%2?'dark':''} ${attempt&&f.bad?'bad':''}">${f.queens[r]===c?'♛':attempt?'·':''}</span>`}).join('')}</div>`;case'points':return plot(f);case'graph':return graph(f);case'intervals':return intervals(f);case'bins':return `<div class="binrow">${f.bins.map((b,i)=>`<div><div class="bin">${b.map((x,j)=>`<span style="height:${x/10}%;background:${['#b5d09b','#d5e6c0','#8fab78','#c3dca8'][j%4]}">${x/1000}</span>`).join('')}</div><div class="row-label">${i+1} · ${b.reduce((a,x)=>a+x,0)/1000}</div></div>`).join('')||'<div class="empty-state">∅<span>尚未开箱</span></div>'}</div>`;default:return '<p>无可显示状态。</p>'}}
